def to_representation(self, instance):
    data = super().to_representation(instance)
    if not self.context["request"].user.is_staff:
        data.pop("internal_notes", None)
    return data

class Book:
    """یک کتاب ساده."""

    def __init__(self, title, author, price):
        # سازنده: هنگام ساخت شیء اجرا می‌شود
        self.title = title
        self.author = author
        self.price = price

    def __str__(self):
        return f"{self.title} by {self.author}"

    def discounted_price(self, percent):
        return round(self.price * (1 - percent / 100), 2)


book = Book("Refactoring", "Martin Fowler", 55.00)
print(book)                            # Refactoring by Martin Fowler
print(book.discounted_price(10))       # 49.5

class Publication:
    def __init__(self, title, year):
        self.title = title
        self.year = year

    def summary(self):
        return f"{self.title} ({self.year})"


class Book(Publication):
    def __init__(self, title, year, author):
        super().__init__(title, year)   # فراخوانی سازنده والد
        self.author = author

    def summary(self):
        # بازنویسی متد والد و گسترش آن
        base = super().summary()
        return f"{base} — {self.author}"


book = Book("Clean Code", 2008, "Robert C. Martin")
print(book.summary())   # Clean Code (2008) — Robert C. Martin

def log_call(func):
    """هر بار که تابع صدا زده شود، یک پیام لاگ می‌کند."""
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__}")
        return func(*args, **kwargs)
    return wrapper


@log_call
def greet(name):
    return f"Hello, {name}!"


greet("Sara")
# Calling greet
# 'Hello, Sara!'

